/* 第04轮紧凑导演工作台，媒体为原创固定测试片。 */
(()=>{
 const C=Cimora,{S,M,E,path,link}=C,D=M.direction,P=M.production;
 const B=(t,a,id='',extra='',cls='cm-button ghost')=>`<button type="button" class="${cls}" data-direct="${a}" data-id="${E(id)}" ${extra}>${t}</button>`;
 const field=(n,t,v,type='text')=>`<label class="cm-label">${t}<input name="${n}" type="${type}" value="${E(String(v??''))}"></label>`;
 const current=c=>{const ss=D.ensure(c);return ss.find(s=>s.id===c.e.selectedShotId)||ss[0];};
 const mediaLabel=m=>`${m.source}；${m.usage}；无声。`;
 function video(v,title){if(v?.media?.url==='assets/direction-group.mp4'&&!v.media.playbackUrl)v={...v,media:{...v.media,playbackUrl:'assets/direction-group-'+(Math.floor(v.media.in/4)+1)+'.mp4'}};return v?.media?`<div class="di-player"><video class="di-video" controls preload="metadata" playsinline aria-label="${E(title)}" data-in="${v.media.playbackUrl?0:v.media.in}" data-out="${v.media.playbackUrl?v.media.out-v.media.in:v.media.out}" src="${E(v.media.playbackUrl||v.media.url)}"></video>${B('播放 / 暂停','play')}</div><details class="di-media-source"><summary>示例媒体来源</summary><small>${E(mediaLabel(v.media))} 来源片段 ${v.media.in}–${v.media.out}秒${v.media.playbackUrl?'（播放预截取的4秒文件）':''}。</small></details>`:'<p class="cm-notice">此旧候选没有真实视频文件，仅保存历史流程记录；不添加假视频。</p>';}
 function preview(c,s){const used=s.candidates.find(v=>v.id===s.adoptedId);return used?`<h3>主预览 · 已采用v${used.version}</h3>${video(used,'主预览 已采用v'+used.version)}`:`<h3>素材预览 · 尚未采用视频</h3>${C.comicShotImage?.(s)||C.art(s.art,s.title)}<p>素材为静态来源，不代表已生成动画。</p>`;}
 function details(c,s){const d=s.direction,cfg=D.profiles[d.profile];return `<details class="cm-panel"><summary>展开导演输入 · 动作、表演、摄影与对白</summary><form data-direct-form="edit" data-id="${s.id}"><div class="di-grid">${field('startProp','开始道具状态',d.startProp)}${field('endProp','结束道具状态',d.endProp)}${field('startPose','开始人物姿态',d.startPose)}${field('endPose','结束人物姿态',d.endPose)}${field('performance','人物表演',d.performance)}${field('framing','景别',d.framing)}${field('camera','运镜',d.camera)}${field('duration','目标时长（4–12秒；测试片固定4秒）',s.duration,'number')}</div><h3>逐条文字 / 说话人</h3><p>导入的全部文字块和原文保留，不合并覆盖；旁白和音效块仍分别保存。</p>${d.lines.map((t,i)=>`<fieldset data-direct-line="${i}"><legend>文字${i+1} · ${E({dialogue:'对白',narration:'旁白',sfx:'音效字'}[t.type]||'对白')}</legend><p>原文：${E(t.originalText||'')}</p><label class="cm-label">校正文案<textarea name="line-${i}">${E(t.text)}</textarea></label>${field('speaker-'+i,'说话人',t.speaker)}</fieldset>`).join('')||'<p>无现有文字块，可新增对白；漫画来源不回写。</p>'}${field('newLine','新增独立对白（可留空）','')}${field('newSpeaker','新增对白说话人','')}<label class="cm-label">能力配置<select name="profile">${Object.entries(D.profiles).map(([k,v])=>`<option value="${k}" ${d.profile===k?'selected':''}>${E(v.name)}</option>`).join('')}</select></label><p>${E(cfg.notice)} 支持用途：${cfg.purposes.map(p=>D.purposes[p]).join(' / ')}；音频：${cfg.audio?'支持':'不支持，测试片无声'}；多镜组合规划：${cfg.multi?'支持':'不支持'}。</p><label><input type="checkbox" name="audio" ${d.audio?'checked':''}>请求音频（不支持时保存会拒绝）</label><button class="cm-button primary">保存详细输入</button></form></details>`;}
 function refs(c,s){const d=s.direction;return `<details class="cm-panel"><summary>当前镜头参考 · ${d.references.length}项，按需选择</summary><p>仅勾选项进入新候选输入；不发送整个项目资产。保存时固定版本，修改不影响其他镜头。源图片可能含原文字，不称无字首帧。</p><form data-direct-form="refs" data-id="${s.id}">${S.state.assets.filter(a=>a.projectId===c.p.id&&['角色','场景','道具','画风'].includes(a.type)).map(a=>refRow('asset',a.id,`${a.type} / ${a.name} v${a.version}`,d)).join('')}${(s.sources||[]).map((r,i)=>refRow('source',String(i),`漫画来源${i+1} / ${r.snapshot.title} v${r.version}`,d)).join('')||''}<button class="cm-button primary">仅保存当前镜头参考</button></form><h4>当前固定引用</h4>${d.references.map(r=>`<p>${E(r.snapshot.name||r.snapshot.title)} v${r.version} · ${E(D.purposes[r.purpose])}</p>`).join('')||'<p>未选参考，只有剧情意图；原始漫画关联仍可追溯。</p>'}</details>`;}
 function refRow(kind,id,label,d){const ref=d.references.find(r=>r.kind===kind&&(kind==='asset'?r.id===id:String(r.sourceIndex)===id)),key=kind+'-'+id;return `<div class="di-ref"><label><input type="checkbox" name="ref" value="${key}" ${ref?'checked':''}>${E(label)}</label><select name="purpose-${key}" aria-label="${E(label)}参考用途">${Object.entries(D.purposes).map(([k,v])=>`<option value="${k}" ${k===(ref?.purpose||'scene')?'selected':''}>${v}${D.profiles[d.profile].purposes.includes(k)?'':'（此配置不支持）'}</option>`).join('')}</select></div>`;}
 function prepare(c,s){const p=s.direction.preparation;return `<details class="cm-panel"><summary>漫画到目标比例 · 首帧准备${p?'（待处理）':''}</summary><p>保留原始漫画、坐标与文字，不执行修复/补画。这里只登记准备要求，不把含字图称为无字首帧。</p><form data-direct-form="prepare" data-id="${s.id}"><label class="cm-label">目标比例<select name="ratio">${['16:9','9:16','1:1'].map(v=>`<option ${p?.ratio===v?'selected':''}>${v}</option>`).join('')}</select></label><label><input type="checkbox" name="repair" ${p?.repair?'checked':''}>申请去字修复（尚未执行）</label><label><input type="checkbox" name="extend" ${p?.extend?'checked':''}>申请边缘补画（尚未执行）</label><button class="cm-button ghost">登记准备要求</button></form>${p?`<p>目标${p.ratio} · 待处理 · ${E(p.notice)}</p>`:''}${(s.sources||[]).map(r=>`<details><summary>来源${E(r.snapshot.title)} v${r.version}</summary>${C.comicSourceDetails(r.snapshot)}</details>`).join('')}</details>`;}
 function neighbors(c,s){const ss=D.ensure(c),i=ss.indexOf(s),prev=ss[i-1],next=ss[i+1];return `<details class="cm-panel"><summary>前后镜头状态对照 · 人工状态规则</summary><div class="di-grid">${[prev,s,next].map((x,j)=>x?`<section><h4>${['前镜','当前','后镜'][j]} · ${E(x.title)}</h4><p>开始：${E(x.direction.startProp||'未填写')} / ${E(x.direction.startPose||'未填写')}</p><p>结束：${E(x.direction.endProp||'未填写')} / ${E(x.direction.endPose||'未填写')}</p>${B('定位此镜头','select',x.id)}</section>`:'<section>无相邻镜头</section>').join('')}</div>${D.continuity(c).filter(x=>x.from===s.id||x.to===s.id).map(x=>`<div class="cm-notice">${x.field==='prop'?'道具':'姿态'}冲突：前镜结束「${E(x.before)}」→后镜开始「${E(x.after)}」。依据：${x.basis}。${B('定位前镜','select',x.from)}${B('定位后镜','select',x.to)}</div>`).join('')}<p>未填写状态不推断冲突；提示为文本规则演示，不代表AI理解视频。</p></details>`;}
 function candidates(c,s){return `<section class="cm-panel"><h3>候选并排比较 · ${s.candidates.length}版</h3>${B('同时播放并排候选','play-pair')}<p>新修改只增加候选。播放器是真实MP4；固定测试片不会实现你的提示词，输入快照另行保存。</p><div class="di-candidates">${s.candidates.map(v=>`<article><h4>v${v.version} · ${v.status==='failed'?'失败':v.id===s.adoptedId?'当前采用':'待采用'}</h4>${v.status==='failed'?'<p>本次流程故障演示，没有视频；旧采用仍在。</p>':video(v,'候选v'+v.version)}<p>输入：${E(v.input.intent)}</p>${v.mode==='direction-demo'?'':`<p>${E(v.warning||'历史模拟记录')}</p>`}${B(v.id===s.adoptedId&&s.direction.adoption?.mode==='automatic-review'?'确认采用此初稿':v.id===s.adoptedId?'已人工采用':'显式采用此版本','adopt',s.id,`data-candidate="${v.id}" ${v.status!=='ready'||v.id===s.adoptedId&&s.direction.adoption?.mode!=='automatic-review'||s.direction.locked?'disabled':''}`)}<details><summary>输入快照 / 来源 / 参考</summary><pre>${E(JSON.stringify(v.input,null,2))}</pre></details></article>`).join('')}</div></section>`;}
 function queue(c){const ss=D.ensure(c),j=c.e.directionJob;return `<details class="cm-panel"><summary>可选：范围生成与自动初稿</summary><p>每组可规划1–3镜；是本机流程模拟，不固定每镜一次实际API。启动后按组推进，可在下一组启动前暂停；刷新自动暂停。锁定镜跳过；自动初稿仅填未采用镜，标“自动选用，待审阅”。</p><form data-direct-form="plan">${ss.map(s=>`<label class="di-range"><input type="checkbox" name="shot" value="${s.id}" checked> ${E(s.title)} · ${s.direction.locked?'锁定，跳过':s.adoptedId?'已采用':'未采用'}</label>`).join('')}<label class="cm-label">每规划组镜头数<select name="groupSize"><option>1</option><option>2</option><option>3</option></select></label><label><input type="checkbox" name="auto">自动初稿（仅补空白采用）</label><label><input type="checkbox" name="fail">让所选范围第一未锁定镜失败（流程演示）</label><button class="cm-button primary">预览所选范围计划</button></form>${B('只重试勾选的失败镜头','retry')}<div>${B('推进下一规划组','advance')}${B('暂停后续组','pause')}${B('继续批次','resume')}${B('停止批次','stop')}</div>${j?`<h4>当前批次：${E({running:'运行中',paused:'已暂停',complete:'完成',stopped:'已停止'}[j.status]||j.status)}</h4><p>${E(j.notice||'')} · 跳过${j.skipped.length}镜</p>${j.groups.map((g,i)=>`<p>组${i+1} · ${E({queued:'未启动',ready:'成功',failed:'失败',skipped:'跳过'}[g.status]||g.status)} · ${g.shots.map(r=>E(D.shot(c,r.id)?.title||r.id)).join(' / ')} · 模拟调用${g.callCount}次</p>`).join('')}`:''}</details>`;}
 const oldMotion=C.productionMotion;C.productionMotion=c=>{if(c.c.kind!=='episode')return oldMotion(c);const s=current(c);if(!s)return oldMotion(c);return `<div class="di-workbench"><header><span class="cm-kicker">SHOT DIRECTION / 04</span><h2>先讲清这段故事，再比较版本。</h2><p>写清剧情，检查动作承接，选择需要的参考，再比较和采用。生成与判断为流程模拟，视频仅作体验样例。</p></header><nav class="di-flow" aria-label="逐镜创作流程">${[['intent','1 剧情意图'],['action','2 动作与承接'],['refs','3 参考与用途'],['generate','4 生成确认'],['compare','5 比较与采用'],['modify','6 局部调优']].map(([step,t])=>B(t,'step',s.id,`data-step="${step}"`)).join('')}</nav><div class="di-shot-tabs">${D.ensure(c).map((x,i)=>B(`${i+1} · ${E(x.title)}${x.direction.locked?' 🔒':''}`,'select',x.id,'',x.id===s.id?'cm-button primary':'cm-button ghost')).join('')}</div><div class="di-main"><section class="cm-panel di-preview">${preview(c,s)}<p>${E(s.direction.adoption?.label||'未设置采用记录')} · ${s.direction.locked?'已锁定':'未锁定'}</p><details class="di-ref-peek"><summary>本镜参考 · ${s.direction.references.length}项</summary><div class="di-selected-refs">${s.direction.references.map(r=>`<figure>${r.kind==='source'?C.comicBaseImage(r.snapshot):C.art(r.snapshot.art||0,r.snapshot.name)}<figcaption>${E(r.snapshot.name||r.snapshot.title)} / ${E(D.purposes[r.purpose])} v${r.version} · 参考示意</figcaption></figure>`).join('')}</div></details>${s.direction.adoption?.mode==='automatic-review'?B('确认采用此初稿','adopt',s.id,`data-candidate="${s.adoptedId}" ${s.direction.locked?'disabled':''}`):''}${B(s.direction.locked?'解锁镜头':'锁定镜头','lock',s.id)}</section><section class="cm-panel"><h3>${E(s.title)}</h3><form data-direct-form="intent" data-id="${s.id}"><label class="cm-label">剧情意图<textarea name="intent" rows="3">${E(s.intent)}</textarea></label><button class="cm-button primary">保存当前镜头意图</button></form><p>已选${s.direction.references.length}参考 · 输入v${s.version} · ${s.candidates.length}候选。采用前先比较。</p>${B('生成新候选 →','generate',s.id)}<details class="di-demo"><summary>演示设置</summary>${B('模拟本镜失败','fail',s.id)}</details><details><summary>用一句话修改已采用片段</summary><form data-direct-form="modify" data-id="${s.id}"><textarea name="instruction" placeholder="例如：先看信再回头" required></textarea><button class="cm-button ghost">保存修改，进入生成确认</button></form><p>旧采用版保留；这是输入/版本流程演示，测试片不随指令生成。</p></details></section></div>${details(c,s)}${refs(c,s)}${prepare(c,s)}${neighbors(c,s)}${candidates(c,s)}${queue(c)}</div>`;};
 // 此页清除重复的原文范围条；不改变故事和其他页面。
 const oldStudio=C.studio;C.studio=c=>{const html=oldStudio(c);return c.c.kind==='episode'&&c.e.view!=='canvas'&&S.context.params.get('stage')==='motion'?'<div class="di-motion-page">'+html.replace(/<section class="cm-notice ad-text-range">[\s\S]*?<\/section>/,'')+'</div>':html;};
 let single=null;function confirmSingle(c,id,options={}){const s=D.shot(c,id);if(D.blocked(c)||s.direction.locked){S.toast(D.blocked(c)||'镜头已锁定，请先解锁');return;}single={project:c.p.id,unit:c.c.id,id,version:s.version,...options};S.modal('确认生成这个镜头',`<h3>${E(s.title)}</h3><p><b>剧情意图：</b>${E(s.intent)}</p><p><b>动作：</b>${E(s.direction.performance||'未填写，沿用剧情意图')}</p><p><b>承接：</b>${E(s.direction.startProp||'开始未填写')} / ${E(s.direction.startPose||'姿态未填写')} → ${E(s.direction.endProp||'结束未填写')} / ${E(s.direction.endPose||'姿态未填写')}</p><p><b>本镜参考：</b>${s.direction.references.map(r=>E((r.snapshot.name||r.snapshot.title)+' · '+D.purposes[r.purpose])).join('；')||'未选择，不携带项目其他素材'}</p><p>${s.direction.lines.length}条独立文字保留 · ${s.duration}秒目标 · ${E(D.profiles[s.direction.profile].name)}</p><p>本次为流程模拟，使用固定示例视频，不执行真实生成或媒体处理。新建候选，不覆盖当前采用版${s.adoptedId?'。':'；生成后需审阅采用。'}${options.fail?'本次体验失败状态。':''}</p>`,B('返回调整','close')+B('确认生成示例候选','confirm-single'));}
 let proposal=null;function planModal(c,j){proposal=j;if(j.error){S.toast(j.error);return;}S.modal('确认范围计划',`<p>${j.groups.length}个规划组 / ${j.groups.reduce((n,g)=>n+g.shots.length,0)}镜头 · 跳过${j.skipped.length}镜 · 模拟$${j.cost.toFixed(2)}</p><p>输入与参考已冻结。启动不立即执行；按“推进下一规划组”逐组体验，暂停后不启动后续组。每组生成媒体片段记录，不是真实API。</p>${j.groups.map((g,i)=>`<p>组${i+1}：${g.shots.map(r=>E(D.shot(c,r.id).title)).join(' / ')}${g.fail?' · 故障演示':''}</p>`).join('')}`,B('取消','close')+B('启动此范围计划','start'));}
 document.addEventListener('click',ev=>{const el=ev.target.closest('[data-direct]');if(!el){const legacy=ev.target.closest('[data-cm="run-plan"],[data-adapt="batch"]');if(legacy&&C.ctx()?.c.kind==='episode'){ev.preventDefault();ev.stopImmediatePropagation();S.route(path(C.ctx(),'motion','flow'));S.toast('请在范围生成中选择镜头并预览计划；锁定镜会跳过');}return;}ev.preventDefault();ev.stopImmediatePropagation();const c=C.ctx(),id=el.dataset.id,a=el.dataset.direct;let error;switch(a){case'play':{const video=el.closest('.di-player').querySelector('video');if(video.paused){if(video.currentTime<Number(video.dataset.in)||video.currentTime>=Number(video.dataset.out)-.1)video.currentTime=Number(video.dataset.in);video.play().catch(()=>S.toast('浏览器未能播放，请使用原生控件重试'));}else video.pause();return;}case'play-pair':S.$$('.di-candidates video').slice(0,2).forEach(video=>{video.currentTime=Number(video.dataset.in);video.play().catch(()=>S.toast('播放未能启动'));});return;case'close':proposal=null;single=null;S.close();S.render();return;case'step':{const selectors={intent:'[data-direct-form="intent"]',action:'[data-direct-form="edit"]',refs:'[data-direct-form="refs"]',generate:'[data-direct="generate"]',compare:'.di-candidates',modify:'[data-direct-form="modify"]'};const target=S.$(selectors[el.dataset.step]);const details=target?.closest('details');if(details)details.open=true;target?.scrollIntoView({block:'center',behavior:'smooth'});return;}case'select':c.e.selectedShotId=id;M.save();S.render();return;case'lock':error=D.lock(c,id,!D.shot(c,id).direction.locked);break;case'generate':case'fail':confirmSingle(c,id,{fail:a==='fail'});return;case'confirm-single':{if(!single)return;const t=single;if(t.project!==c.p.id||t.unit!==c.c.id||D.shot(c,t.id)?.version!==t.version){S.toast('镜头已变化，请重新确认');return;}const r=D.generate(c,t.id,{fail:t.fail,instruction:t.instruction});error=r.error;if(!error){single=null;S.close();S.toast('新候选已就绪，请比较后决定是否采用；旧采用版保留');}break;}case'adopt':error=D.adopt(c,id,el.dataset.candidate);break;case'start':error=D.start(c,proposal);if(!error){proposal=null;S.close();}break;case'advance':D.advance(c);break;case'pause':D.pause(c);break;case'resume':D.resume(c);break;case'stop':D.stop(c);break;case'retry':planModal(c,D.retry(c,S.$$('[data-direct-form="plan"] [name="shot"]:checked').map(e=>e.value)));return;}if(error)S.toast(error);S.render();},true);
 document.addEventListener('submit',ev=>{const f=ev.target.closest('[data-direct-form]');if(!f)return;ev.preventDefault();ev.stopImmediatePropagation();const c=C.ctx(),id=f.dataset.id,s=id&&D.shot(c,id),fd=new FormData(f),v=Object.fromEntries(fd);let error;switch(f.dataset.directForm){case'intent':error=D.edit(c,id,{intent:v.intent});break;case'edit':{const lines=s.direction.lines.map((t,i)=>({...t,text:v['line-'+i],speaker:v['speaker-'+i]}));if(v.newLine?.trim())lines.push({id:S.id('line'),originalText:v.newLine,text:v.newLine,speaker:v.newSpeaker||'未指定',type:'dialogue'});error=D.edit(c,id,{...v,audio:!!v.audio,lines});break;}case'refs':{const refs=fd.getAll('ref').map(key=>{const kind=key.startsWith('asset-')?'asset':'source',refid=key.slice(kind.length+1);return {kind,...(kind==='asset'?{id:refid}:{sourceIndex:Number(refid)}),purpose:v['purpose-'+key]};});error=D.references(c,id,refs);break;}case'prepare':error=D.prepare(c,id,{...v,repair:!!v.repair,extend:!!v.extend});break;case'modify':{if(!s.adoptedId){error='先显式采用一个版本再修改';break;}error=D.edit(c,id,{intent:v.instruction});if(!error){S.navigationSaved?.(f,true);confirmSingle(c,id,{instruction:v.instruction});return;}break;}case'plan':{const ids=fd.getAll('shot'),first=D.ensure(c).find(s=>ids.includes(s.id)&&!s.direction.locked);planModal(c,D.plan(c,ids,{groupSize:v.groupSize,auto:!!v.auto,failIds:v.fail&&first?[first.id]:[]}));return;}}S.navigationSaved?.(f,!error);if(error)S.toast(error);else S.toast('已保存；旧采用版与来源完整保留');S.render();},true);
 const oldAfter=C.afterRender;C.afterRender=r=>{oldAfter(r);S.$$('.di-video').forEach(video=>{const start=Number(video.dataset.in),end=Number(video.dataset.out);video.addEventListener('loadedmetadata',()=>{if(start)video.currentTime=start;});if(video.readyState>=1&&start)video.currentTime=start;video.addEventListener('timeupdate',()=>{if(video.currentTime>=end){video.pause();video.currentTime=start;}});});};
})();









